from .ranges import parse


def _not_satisfiable(length):
    headers = {'Content-Range': 'bytes */%d' % length, 'Content-Length': '0'}
    return 416, headers, b''


def serve(data, range_header=None):
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    try:
        kind, a, b = parse(range_header)
    except ValueError:
        # Every range on empty data is unsatisfiable, and so is any
        # header that does not match the grammar at all.
        return _not_satisfiable(length)
    if length == 0:
        return _not_satisfiable(0)

    if kind == 'full':
        start, end = a, b
        if end < start:  # reverse bounds
            return _not_satisfiable(length)
        if start >= length:  # start beyond EOF
            return _not_satisfiable(length)
        end = min(end, length - 1)  # clamp end past EOF
    elif kind == 'prefix':
        start = a
        if start >= length:
            return _not_satisfiable(length)
        end = length - 1
    else:  # suffix
        n = a
        if n == 0:  # zero suffix
            return _not_satisfiable(length)
        start = length - n if n < length else 0
        end = length - 1

    body = data[start:end + 1]  # inclusive end
    headers = {'Content-Length': str(len(body)),
               'Content-Range': 'bytes %d-%d/%d' % (start, end, length)}
    return 206, headers, body
